package org.humanjourney.core.advancement;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import net.minecraft.advancements.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.client.gui.screens.advancements.*;
import org.humanjourney.core.advancement.client.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
class NativeAdapterTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();}
 @AfterAll static void close(){loader.close();}
 @AfterEach void clear(){NativeAdapter.restoreAll();NativeClient.STATE.clear();}
 record Fixture(AdvancementTab tab,Map<String,NativeWidgetAccess> widgets,int[] bounds,double[] scroll){}
 Fixture fixture(String rootId)throws Exception{var tab=mock(AdvancementTab.class,withSettings().extraInterfaces(NativeTabAccess.class));var access=(NativeTabAccess)tab;var root=mock(AdvancementNode.class);when(root.holder()).thenReturn(new AdvancementHolder(ResourceLocation.parse(rootId),mock(Advancement.class)));when(tab.getRootNode()).thenReturn(root);var map=new LinkedHashMap<AdvancementHolder,AdvancementWidget>();var bridges=new HashMap<String,NativeWidgetAccess>();int index=0;for(String id:List.of(rootId,"human_journey:era0/we_can_stay","human_journey:era0/survival/rest_at_last")){var w=mock(AdvancementWidget.class,withSettings().extraInterfaces(NativeWidgetAccess.class));var a=(NativeWidgetAccess)w;var x=new AtomicInteger(index++*28);var y=new AtomicInteger(0);when(a.hjId()).thenReturn(id);when(a.hjParent()).thenReturn("");when(a.hjDrawn()).thenReturn(true);when(a.hjX()).thenAnswer(q->x.get());when(a.hjY()).thenAnswer(q->y.get());doAnswer(q->{x.set(q.getArgument(0));y.set(q.getArgument(1));return null;}).when(a).hjPosition(anyInt(),anyInt());map.put(new AdvancementHolder(ResourceLocation.parse(id),mock(Advancement.class)),w);bridges.put(id,a);}when(access.hjWidgets()).thenReturn(map);int[] bounds=new int[4];double[] scroll={0,0};doAnswer(q->{for(int i=0;i<4;i++)bounds[i]=q.getArgument(i);return null;}).when(access).hjBounds(anyInt(),anyInt(),anyInt(),anyInt());when(access.hjScrollX()).thenAnswer(q->scroll[0]);when(access.hjScrollY()).thenAnswer(q->scroll[1]);doAnswer(q->{scroll[0]=q.getArgument(0);scroll[1]=q.getArgument(1);return null;}).when(access).hjScroll(anyDouble(),anyDouble());return new Fixture(tab,bridges,bounds,scroll);}
 void load(NativePresentation model,long sequence){NativePackets.frames(new UUID(0,170),sequence,model).forEach(NativeClient.STATE::accept);}
 @Test void manualCoordinatesMoveNativeWidgetsAndUpdateVanillaScrollBounds()throws Exception{var f=fixture("human_journey:era0/root");load(NativePresentationTest.parse(NativePresentationTest.example()),1);NativeAdapter.prepare(f.tab);assertEquals(490,f.widgets.get("human_journey:era0/we_can_stay").hjX());assertEquals(74,f.widgets.get("human_journey:era0/we_can_stay").hjY());assertEquals(518,f.bounds[2]);assertEquals(-74,f.scroll[1]);assertEquals(0,f.bounds[0]);assertEquals(34,f.bounds[1]);}
 @Test void panningIsNotResetByEveryRenderAndReopenGetsSameLayout()throws Exception{var model=NativePresentationTest.parse(NativePresentationTest.example());var a=fixture("human_journey:era0/root");load(model,1);NativeAdapter.prepare(a.tab);a.scroll[0]=-190;a.scroll[1]=-64;for(int i=0;i<100;i++)NativeAdapter.prepare(a.tab);assertEquals(-190,a.scroll[0]);assertEquals(-64,a.scroll[1]);var b=fixture("human_journey:era0/root");NativeAdapter.prepare(b.tab);assertEquals(490,b.widgets.get("human_journey:era0/we_can_stay").hjX());}
 @Test void missingOrInvalidPresentationRestoresOriginalCoordinates()throws Exception{var f=fixture("human_journey:era0/root");load(NativePresentationTest.parse(NativePresentationTest.example()),1);NativeAdapter.prepare(f.tab);load(NativePresentation.empty(),2);NativeAdapter.prepare(f.tab);assertEquals(28,f.widgets.get("human_journey:era0/we_can_stay").hjX());assertEquals(0,f.widgets.get("human_journey:era0/we_can_stay").hjY());}
 @Test void ordinaryTabsAreNotTouched()throws Exception{var f=fixture("minecraft:story/root");load(NativePresentationTest.parse(NativePresentationTest.example()),1);NativeAdapter.prepare(f.tab);verify((NativeTabAccess)f.tab,never()).hjWidgets();for(var a:f.widgets.values())verify(a,never()).hjPosition(anyInt(),anyInt());}
 @Test void hiddenNativeWidgetsKeepTheirOriginalPosition()throws Exception{var f=fixture("human_journey:era0/root");var cap=f.widgets.get("human_journey:era0/we_can_stay");when(cap.hjDrawn()).thenReturn(false);load(NativePresentationTest.parse(NativePresentationTest.example()),1);NativeAdapter.prepare(f.tab);assertEquals(28,cap.hjX());assertEquals(0,cap.hjY());}
 @Test void realNativeAncestryValidationRejectsCrossRootWithoutAnyAward()throws Exception{var model=NativePresentationTest.parse(NativePresentationTest.example());var values=new HashMap<String,AdvancementHolder>();for(String id:model.tabs().getFirst().ids()){var a=mock(Advancement.class);when(a.display()).thenReturn(Optional.of(mock(DisplayInfo.class)));when(a.parent()).thenReturn(id.equals(model.tabs().getFirst().root())?Optional.empty():Optional.of(ResourceLocation.parse(model.tabs().getFirst().root())));values.put(id,new AdvancementHolder(ResourceLocation.parse(id),a));}assertDoesNotThrow(()->NativeServer.validate(model,values::get));when(values.get("human_journey:era0/we_can_stay").value().parent()).thenReturn(Optional.empty());assertThrows(IllegalArgumentException.class,()->NativeServer.validate(model,values::get));}
}
